	// Single-step: one Start rising edge triggers exactly one automatic action
	MoveDown := FALSE;
	MoveUp := FALSE;
	MoveLeft := FALSE;
	MoveRight := FALSE;
	ActivateGrip := FALSE;
	ActivateRelease := FALSE;
	IF rtrigStart.Q AND NOT xStepHold THEN
		eStep := (eStep MOD 8) + 1;
		xStepHold := TRUE;
	END_IF;
	IF xStepHold THEN
		CASE eStep OF
			1:	MoveDown := NOT DownLimitSwitch;
				IF DownLimitSwitch THEN
					xStepHold := FALSE;
				END_IF;
			2:	ActivateGrip := NOT GripLimitSwitch;
				IF GripLimitSwitch THEN
					xStepHold := FALSE;
				END_IF;
			3:	MoveUp := NOT UpLimitSwitch;
				IF UpLimitSwitch THEN
