				END_IF;
			4:	MoveRight := NOT RightLimitSwitch;
				IF RightLimitSwitch THEN
					xStepHold := FALSE;
				END_IF;
			5:	MoveDown := NOT DownLimitSwitch;
				IF DownLimitSwitch THEN
					xStepHold := FALSE;
				END_IF;
			6:	ActivateRelease := NOT ReleaseLimitSwitch;
				IF ReleaseLimitSwitch THEN
					xStepHold := FALSE;
				END_IF;
			7:	MoveUp := NOT UpLimitSwitch;
				IF UpLimitSwitch THEN
					xStepHold := FALSE;
				END_IF;
			8:	MoveLeft := NOT LeftLimitSwitch;
				IF LeftLimitSwitch THEN
					xStepHold := FALSE;
				END_IF;
		END_CASE;
	END_IF;

ELSIF xModeCycle OR xModeCont THEN
	// Single-cycle / continuous: one Start rising edge starts the full automatic sequence
	MoveDown := FALSE;
	MoveUp := FALSE;
	MoveLeft := FALSE;
	MoveRight := FALSE;
	ActivateGrip := FALSE;
	ActivateRelease := FALSE;
	IF rtrigStart.Q AND NOT xAutoActive THEN
		xAutoActive := TRUE;
		eStep := 1;
	END_IF;
	IF xAutoActive THEN
		CASE eStep OF
			1:	MoveDown := NOT DownLimitSwitch;
				IF DownLimitSwitch THEN
					eStep := 2;
				END_IF;
			2:	ActivateGrip := NOT GripLimitSwitch;
				IF GripLimitSwitch THEN
					eStep := 3;
				END_IF;
			3:	MoveUp := NOT UpLimitSwitch;
				IF UpLimitSwitch THEN
					eStep := 4;
				END_IF;
			4:	MoveRight := NOT RightLimitSwitch;
				IF RightLimitSwitch THEN
					eStep := 5;
				END_IF;
			5:	MoveDown := NOT DownLimitSwitch;
				IF DownLimitSwitch THEN
					eStep := 6;
				END_IF;
			6:	ActivateRelease := NOT ReleaseLimitSwitch;
				IF ReleaseLimitSwitch THEN
					eStep := 7;
				END_IF;
			7:	MoveUp := NOT UpLimitSwitch;
				IF UpLimitSwitch THEN
					eStep := 8;
				END_IF;
